"l\xED{\x9C\x13\x92\xC0\xECW\xE6\xD6-\x9F\x80\x08\xCC\x86\xFD\xC1t<\xB5\x9A\x86",'alse end\n    -- Chong cau tren troi: dang bay / khong o tren nuoc thi bo qua lan cast nay\n    if not NexusState.canCastNow() then return false end\n    Fishing.BossFarm.LastCast = tick()\n    resetBossFarmTarget()\n    pcall(function()\n        local root = character:FindFirstChild("HumanoidRootPart")\n        if root then Events.Fishing:FireServer(root.CFrame) end\n    end)\n    return true\nend\n\nlocal function farmHookedBoss(target)\n    if not bossFarmEnabled() then return end\n    local shouldFarm, targetType = shouldFarmBossTarget(target)\n    if not shouldFarm then return end\n    Fishing.BossFarm.CurrentType = targetType\n    local notifyKey = targetType .. tostring(target.Name)\n    if Fishing.BossFarm.LastNotify ~= notifyKey then\n        Fishing.BossFarm.LastNotify = notifyKey\n        NexusLib:Notify({ Title = "Boss Farm", Message = "Farming " .. targetType .. ": " .. tostring(target.Name or "Unknown"), Duration = 3 })\n    end\n    if tick() - Fishing.BossFarm.LastProgress > 0.04 then\n        Fishing.BossFarm.LastProgress = tick()\n        pcall(function() Events.UpdateFishProgression:FireServer() end)\n    end\nend\n\n-- MAIN LOOPS\ntask.spawn(function()\n    while true do\n        local waitTime = 0.5 + math.random(0, 30) / 100\n        task.wait(waitTime)\n        if not alive() then break end\n        if Fishing.Flags.MainFarm and (Fishing.Flags.AutoCast or Fishing.Flags.AutoSkill or Fishing.Flags.AntiAFK) then\n            if Fishing.Flags.AutoCast then\n                local c = LocalPlayer.Character\n                if c then\n                    -- Fix freeze: khong force cast khi player dang di chuyen\n                    local moving = false\n                    pcall(function()\n                        local hum = c:FindFirstChildOfClass("Humanoid")\n                        if hum and hum.MoveDirection then\n                            local md = hum.MoveDirection\n                            moving = math.abs(md.X or 0) + math.abs(md.Z or 0) > 0.05\n                        end\n                    end)\n                    if (not c:GetAttribute("Fishing")) and not moving and NexusState.canCastNow() then\n                        pcall(function() Events.Fishing:FireServer() end)\n                    elseif NexusState.isDoingUseBaitQuest and MainGui:FindFirstChild("Fishing") and MainGui.Fishing.Visible then\n                        pcall(function()\n                            local root = c:FindFirstChild("HumanoidRootPart")\n                            Events.Fishing:FireServer(root and root.CFrame or nil)\n                        end)\n                    end\n                end\n            end\n            if Fishing.Flags.AutoSkill and MainGui:FindFirstChild("Fishing") and MainGui.Fishing.Visible then\n                pcall(function()\n                    local char = LocalPlayer.Character\n                    local skillsFolder = char and char:FindFirstChild("Skills")\n                    if skillsFolder then\n                        local readySkills = {}\n                        for _, skill in ipairs(skillsFolder:GetChildren()) do\n                            if typeof(skill) == "Instance" and skill:IsA("NumberValue") and skill.Value <= 0 then\n                                local key = skill:GetAttribute("Key")\n                                if key then readySkills[key] = true end\n                            end\n                        end\n\n                        if Fishing.Flags.SkillMode == "Sequential" then\n                            local now = tick()\n                            local delay = Fishing.Flags.SkillDelay or 0.3\n                            if now - (NexusState.lastSkillCastTime or 0) >= delay then\n                                local seqStr = Fishing.Flags.SkillSequence or "Z,X,C,V"\n                                local seq = {}\n                                for k in string.gmatch(seqStr:upper(), "[ZXCV]") do\n                                    table.insert(seq, k)\n                                end\n                                if #seq == 0 then seq = {"Z", "X", "C", "V"} end\n\n                                local attempts = 0\n                                while attempts < #seq do\n                                    attempts = attempts + 1\n                                    if not NexusState.skillSeqIndex or NexusState.skillSeqIndex > #seq then\n                                        NexusState.skillSeqIndex = 1\n                                    end\n                                    local targetKey = seq[NexusState.skillSeqIndex]\n                                    NexusState.skillSeqIndex = NexusState.skillSeqIndex + 1\n                                    if readySkills[targetKey] then\n                                        Events.UseSkill:FireServer(targetKey)\n                                        NexusState.lastSkillCastTime = now\n                                        break\n                                    end\n                                end\n                            end\n                        else\n                            local selectedSkills = Fishing.Flags.SelectedSkills or {"Z", "X", "C", "V"}\n                            for _, key in ipairs(selectedSkills) do\n                                if readySkills[key] then\n                                    Events.UseSkill:FireServer(key)\n                                end\n                            end\n                        end\n                    end\n                end)\n            else\n                NexusState.skillSeqIndex = 1\n            end\n            if Fishing.Flags.AntiAFK and tick() - (NexusState.lastAfkFire or 0) > 60 then\n                local _afkMoving = false\n                pcall(function()\n                    local _c = LocalPlayer.Character\n                    local _h = _c and _c:FindFirstChildOfClass("Humanoid")\n                    local _md = _h and _h.MoveDirection\n                    if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _afkMoving = true end\n                end)\n                if not _afkMoving then\n                    NexusState.lastAfkFire = tick()\n                    pcall(function() Events.AFK:FireServer() end)\n                end\n            end\n        end\n    end\nend)\n\n-- SMART SECRET WEATHER OVERRIDE LOOP\ntask.spawn(function()\n    local weatherIslandsMap = {\n        ["thunderstorm"] = "Island 2",\n        ["rainy"]        = "Island 3",\n        ["windy"]        = "Island 5",\n        ["snowy"]        = "Island 6",\n        ["frost"]        = "Island 6",\n        ["foggy"]        = "Island 7",\n        ["blazing sun"]  = "Island 8",\n    }\n\n    local function getActiveWeather()\n        local info = MainGui:FindFirstChild("Info")\n        if info then\n            local infoFrame = info:FindFirstChild("Info")\n            if infoFrame then\n                local weatherFrame = infoFrame:FindFirstChild("Weather")\n                if weatherFrame then\n                    local val = weatherFrame:FindFirstChild("Value")\n                    if val and typeof(val) == "Instance" then\n                        local text = ((typeof(val) == "Instance" and val:IsA("TextLabel") and val.Text or val.Value))\n                        return text:gsub("Weather:%s*", ""):lower():gsub("^%s+", ""):gsub("%s+$", "")\n                    end\n                end\n            end\n        end\n        return "clear"\n    end\n\n    while true do\n        task.wait(1.5)\n        if not alive() then break end\n        if NexusState.SmartWeather and NexusState.SmartWeather.enabled then\n            pcall(function()\n                local currentWeather = getActiveWeather()\n                local matchedIsland = weatherIslandsMap[currentWeather]\n\n                if matchedIsland and (currentWeather ~= "clear" and cur