           end\n        })\n    end\n\nend\n\n-- ============================================================\n-- ===== SHOP TAB =====\n-- ============================================================\ndo\n    local ShopTab = Window:CreateTab(\"Shop\")\n\n    -- Index\n    do\n        local IndexSection = ShopTab:CreateSection(\"Index\")\n        IndexSection:CreateButton({\n            Name = \"Unlock all fish\",\n            Callback = function()\n                local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                if not userData then\n                    NexusLib:Notify({ Title = \"Index\", Message = \"User data not found!\", Duration = 2 })\n                    return\n                end\n                local indexFolder = userData:FindFirstChild(\"Index\")\n                if not indexFolder then\n                    NexusLib:Notify({ Title = \"Index\", Message = \"Index folder not found!\", Duration = 2 })\n                    return\n                end\n                local count = 0\n                for _, child in ipairs(indexFolder:GetChildren()) do\n                    if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") or child:IsA(\"IntValue\") then\n                        child.Value = 1\n                        count = count + 1\n                    elseif typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"BoolValue\") then\n                        child.Value = true\n                        count = count + 1\n                    end\n                end\n            end\n        })\n    end\n\n    -- Upgrade Skill\n    do\n        local UpgradeSkillSection = ShopTab:CreateSection(\"Upgrade Skill\")\n        local function GetOwnedSkills()\n            local userId = LocalPlayer and LocalPlayer.UserId\n            if not userId then return {} end\n            local userData = Data and Data:FindFirstChild(tostring(userId))\n            if not userData then return {} end\n            local skillFolder = userData:FindFirstChild(\"Skill\")\n            if not skillFolder then return {} end\n            local ownedSkills = {}\n            for _, child in pairs(skillFolder:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Folder\") then\n                    local owned = child:FindFirstChild(\"Owned\")\n                    if typeof(owned) == \"Instance\" and owned:IsA(\"BoolValue\") and owned.Value == true then\n                        table.insert(ownedSkills, child.Name)\n                    end\n                end\n            end\n            return ownedSkills\n        end\n\n        local skillOptions = GetOwnedSkills()\n        if #skillOptions == 0 then skillOptions = {\"No skill owned\"} end\n        local selectedSkill = skillOptions[1] or \"No skill owned\"\n\n        local skillDropdown = Cfg.register(UpgradeSkillSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose A Skill That Needs To Upgrade\", {\n            Name = \"Choose A Skill That Needs To Upgrade\",\n            Options = skillOptions,\n            Default = selectedSkill,\n            Callback = function(value) selectedSkill = value end\n        })), \"Dropdown\", \"Choose A Skill That Needs To Upgrade\", {\n            Name = \"Choose A Skill That Needs To Upgrade\",\n            Options = skillOptions,\n            Default = selectedSkill,\n            Callback = function(value) selectedSkill = value end\n        })\n\n        local upgradeSkillMethodDropdown = Cfg.register(UpgradeSkillSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Upgrade Method\", {\n            Name = \"Upgrade Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.upgradeSkill.method or \"Instant\",\n            Callback = function(value) NexusState.upgradeSkill.method = value end\n        })), \"Dropdown\", \"Upgrade Method\", {\n            Name = \