yb\",\n            [\"Upgrade Skill\"] = \"Ulepsz umiejtno\",\n            [\"Craft Rod\"] = \"Stwrz wdk\",\n            [\"Auto Buy Bait\"] = \"Auto kup przynt\",\n            [\"Auto Buy Rod\"] = \"Auto kup wdk\",\n            [\"Learn Skills\"] = \"Ucz si umiejtnoci\",\n            [\"Trait Reroll\"] = \"Losowanie cechy\",\n            [\"Craft Bait\"] = \"Stwrz przynt\",\n            [\"Auto Gacha\"] = \"Auto gacha\",\n            [\"Exchange Items\"] = \"Wymie przedmioty\",\n            [\"Auto Claim Ticket Quest\"] = \"Auto odbierz misj biletow\",\n            [\"Daily Quests\"] = \"Codzienne zadania\",\n            [\"Material Farming\"] = \"Farm materiaw\",\n            [\"Auto Do Ticket Quest\"] = \"Auto wykonaj misj biletow\",\n            [\"Character Upgrade\"] = \"Ulepsz posta\",\n            [\"Character\"] = \"Posta\",\n            [\"World & Misc\"] = \"wiat i inne\",\n            [\"Streamer Mode (Fake Name)\"] = \"Tryb streamera (faszywa nazwa)\",\n            [\"Language & Localization\"] = \"Jzyk i lokalizacja\",\n            [\"Nexus Shield\"] = \"Tarcza Nexus\",\n            [\"Staff Watch\"] = \"Wykrywanie staffu\",\n            [\"ESP\"] = \"ESP\",\n            [\"Lock catch bar\"] = \"Zablokuj pasek apania\",\n            [\"Auto Cast\"] = \"Auto zarzucanie\",\n            [\"Auto Farm Boss\"] = \"Auto farm bossw\",\n            [\"Auto Farm Secret Boss\"] = \"Auto farm sekretnych bossw\",\n            [\"Auto Skill\"] = \"Auto umiejtnoci\",\n            [\"Auto Sell Fish\"] = \"Auto sprzeda ryb\",\n            [\"Auto Enzo\"] = \"Auto Enzo QTE\",\n            [\"Anti AFK\"] = \"Anti-AFK\",\n            [\"Farm On Weather\"] = \"Auto zmiana wyspy wg pogody\",\n            [\"Auto Equip Best Bait\"] = \"Auto za najlepsz przynt\",\n            [\"Auto Equip Fishing Rod (Slot 1)\"] = \"Auto za wdk (slot 1)\",\n            [\"Auto Nameless\"] = \"Auto Bezymienny\",\n            [\"Auto Favourite Fishes\"] = \"Auto ulubione ryby\",\n            [\"Auto Teleport + Interact (Pray) Spirit\"] = \"Auto teleport do ducha i modlitwa\",\n            [\"Enable Auto Farm Fish\"] = \"Wcz auto farm ryb\",\n            [\"Auto Do Daily Quest\"] = \"Auto dzienne zadanie\",\n            [\"Auto Do Ticket Quest (Fast)\"] = \"Auto misja biletowa (szybko)\",\n            [\"Auto Claim Ticket Quest (Fast)\"] = \"Auto odbierz bilet (szybko)\",\n            [\"Auto Rebirth\"] = \"Auto odrodzenie\",\n            [\"Auto craft bait\"] = \"Auto twrz przynt\",\n            [\"Auto craft selected rod\"] = \"Auto twrz wybran wdk\",\n            [\"Auto fish for bait materials\"] = \"Auto w materiay na przynt\",\n            [\"Fly Mode\"] = \"Tryb latania\",\n            [\"Walk On Water\"] = \"Chodzenie po wodzie\",\n            [\"Infinite Jump\"] = \"Nieskoczony skok\",\n            [\"Noclip\"] = \"Noclip\",\n            [\"Full Bright\"] = \"Pena jasno\",\n            [\"Fake Name Display\"] = \"Poka faszyw nazw\",\n            [\"Anti-Report Nexus Users\"] = \"Chro uytkownikw Nexus przed reportami\",\n            [\"Enable Staff Watch\"] = \"Wcz wykrywanie staffu\",\n            [\"Enable Notifications\"] = \"Wcz powiadomienia\",\n            [\"Ignore Locked\"] = \"Ignoruj zablokowane\",\n            [\"Performance Mod\"] = \"Tryb wydajnoci (FPS)\",\n            [\"NPCs ESP\"] = \"ESP NPC\",\n            [\"Secret Rod ESP\"] = \"ESP sekretnej wdki\",\n            [\"Boat ESP\"] = \"ESP odzi\",\n            [\"God ESP\"] = \"ESP boskiego bossa\",\n            [\"Review update v2.2\"] = \"Zobacz aktualizacj v2.2\",\n            [\"Equip Best Rod\"] = \"Za najlepsz wdk\",\n[\"Equip Best Orb\"] = \"Za najlepszy orb\",\n            [\"Teleport to Nameless Octoparasite\"] = \"Teleport do Bezymiennej Omiornicy\",\n            [\"Unlock all fish\"] = \"Odblokuj wszystkie ryby\",\n            [\"Upgrade Selected Skill\"] = \"Ulepsz wybran umiejtno\",\n            [\"Craft rod now\"] = \"Stwrz wdk teraz\",\n            [\"Buy Now\"] = \"Kup teraz\",\n            [\"Buy Selected Rod\"] = \"Kup wybran wdk\",\n            [\"Learn Selected Skills\"] = \"Naucz si wybranych umiejtnoci\",\n            [\"Reroll Until Trait\"] = \"Losuj a do cechy\",\n            [\"Craft bait now\"] = \"Stwrz przynt teraz\",\n            [\"Exchange now\"] = \"Wymie teraz\",\n            [\"Claim Daily Rewards\"] = \"Odbierz dzienne nagrody\",\n            [\"Check Resources\"] = \"Sprawd zasoby\",\n            [\"Redeem All Codes\"] = \"Wykorzystaj wszystkie kody\",\n            [\"Refresh List\"] = \"Odwie list\",\n            [\"Delete Job ID\"] = \"Usu Job ID\",\n            [\"Join by Job ID\"] = \"Docz przez Job ID\",\n            [\"Check Current Players\"] = \"Sprawd obecnych graczy\",\n            [\"Teleport to Player\"] = \"Teleport do gracza\",\n            [\"Spectate Player\"] = \"Obserwuj gracza\",\n            [\"Teleport To Current Weather\"] = \"Teleport na wysp z obecn pogod\",\n            [\"Teleport to Recommend Is\n-- ============================================================\ndo\n    local TeleportTab = Window:CreateTab(\"Teleport\")\n    local TPSection = TeleportTab:CreateSection(\"NPC & Weather\", \"Left\")\n\n    TPSection:CreateButton({\n        Name = \"TP to Taoist\",\n        Callback = function()\n            local taoist = nil\n            for _, v in pairs(Workspace:GetDescendants()) do\n                if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Model\") and string.find(v.Name:lower(), \"taoist\") and v:FindFirstChild(\"HumanoidRootPart\") then\n                    taoist = v\n                    break\n                end\n            end\n            if taoist and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = taoist.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)\n                NexusLib:Notify({ Title = \"Taoist\", Message = \"Teleported!\", Duration = 3 })\n            else\n                NexusLib:Notify({ Title = \"Taoist\", Message = \"Not found!\", Duration = 3 })\n            end\n        end\n    })\n\n    TPSection:CreateButton({\n        Name = \"TP to Maoshan\",\n        Callback = function()\n            local maoshan = nil\n            for _, v in pairs(Workspace:GetDescendants()) do\n                if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Model\") and (string.find(v.Name:lower(), \"maoshan\") or string.find(v.Name:lower(), \"merchant\")) and v:FindFirstChild(\"HumanoidRootPart\") then\n                    maoshan = v\n                    break\n                end\n            end\n            if maoshan and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = maoshan.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)\n                NexusLib:Notify({ Title = \"Maoshan\", Message = \"Teleported!\", Duration = 3 })\n            else\n                NexusLib:Notify({ Title = \"Maoshan\", Message = \"Not found!\", Duration = 3 })\n            end\n        end\n    })\n\n    TPSection:CreateButton({\n        Name = \"TP to Spirit\",\n        Callback = function()\n            local godFolder = Workspace:FindFirstChild(\"NPC\") and Workspace.NPC:FindFirstChild(\"God\")\n            if not godFolder then\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"Folder God not found!\", Duration = 3 })\n                return\n            end\n            local target = nil\n            for _, child in pairs(godFolder:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Model\") then\n                    local hrp = child:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        target = hrp\n                        break\n                    end\n                elseif typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"BasePart\") then\n                    target = child\n                    break\n                end\n            end\n            if not target then\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"No Spirit found!\", Duration = 3 })\n                return\n            end\n            local char = LocalPlayer.Character\n            if not char then return end\n            local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n            if hrp then\n                hrp.CFrame = target.CFrame + Vector3.new(0, 3, 0)\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"Teleported to Spirit!\", Duration = 3 })\n            end\n        end\n    })\n\n    -- ===== NPC TELEPORT + GIVE FISH (Duan Gan / Dumb guy) =====\n    do\n        local GiveSection = TeleportTab:CreateSection(\"Quest NPC & Give Fish\", \"Right\")\n\n        local function npcRoot()\n            return Workspace:FindFirstChild(\"NPC\")\n        end\n\n        local function findNpcHrp(npcName)\n            local hrp = nil\n            pcall(function()\n                local npcFolder = npcRoot()\n                if not npcFolder then return end\n                local f = npcFolder:FindFirstChild(\"Function\")\n                local m = (f and f:FindFirstChild(npcName)) or npcFolder:FindFirstChild(npcName)\n                if m then hrp = m:FindFirstChild(\"HumanoidRootPart\") or m:FindFirstChild(\"Torso\") end\n            end)\n            return hrp\n        end\n\n        local function teleportNearNpc(npcName, offset)\n            local hrp = findNpcHrp(npcName)\n            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            if not hrp or not root then return false end\n            pcall(function()\n                root.CFrame = CFrame.new(hrp.Position + (offset or Vector3.new(0, 3, 0)))\n            end)\n            return true\n        end\n\n        local function parseWeightKg(text)\n            local clean = string.gsub(text, \"[,%s]\", \"\")\n            local num, suffix = string.match(clean, \"(%d+%.?%d*)([KkMmBbTt]?)\")\n            local n = tonumber(num) or 0\n            if suffix == \"K\" or suffix == \"k\" then\n                n = n * 1000\n            elseif suffix == \"M\" or suffix == \"m\" then\n                n = n * 1000000\n            elseif suffix == \"B\" or suffix == \"b\" then\n                n = n * 1000000000\n            elseif suffix == \"T\" or suffix == \"t\" then\n                n = n * 1000000000000\n            end\n            return n\n        end\n\n        local function getFishKg(item)\n            local w = 0\n            pcall(function()\n                local attr = item:GetAttribute(\"Weight\")\n                if tonumber(attr) and tonumber(attr) > 0 then\n                    w = tonumber(attr)\n                elseif typeof(item) == \"Instance\" and typeof(item) == \"Instance\" and item:IsA(\"StringValue\") then\n                    local parts = {}\n                    for part in string.gmatch(item.Value, \"[^|]+\") do table.insert(parts, part) end\n                    if #parts >= 2 then w = parseWeightKg(parts[2]) end\n                elseif typeof(item) == \"Instance\" and typeof(item) == \"Instance\" and item:IsA(\"NumberValue\") or item:IsA(\"IntValue\") then\n                    w = tonumber(item.Value) or 0\n                end\n            end)\n            return w\n        end\n\n        local function collectBigFish(minKg)\n            local out = {}\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            local inv = userData and userData:FindFirstChild(\"Inventory\")\n            if not inv then return out end\n            for _, item in pairs(inv:GetChildren()) do\n                local kg = getFishKg(item)\n                if kg >= minKg then\n                    table.insert(out, { item = item, name = item.Name, kg = kg })\n                end\n            end\n            table.sort(out, function(a, b) return a.kg > b.kg end)\n            return out\n        end\n\n        local function giveFishToDumbGuy(entry)\n            if not entry or not entry.item then return false end\n            local model = nil\n            pcall(function()\n                local npcFolder = npcRoot()\n                local f = npcFolder and npcFolder:FindFirstChild(\"Function\")\n                model = f and f:FindFirstChild(\"Dumb guy\")\n            end)\n            if not model then return false end\n            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            local origCF = root and root.CFrame\n            if teleportNearNpc(\"Dumb guy\", Vector3.new(0, 3, 0)) then task.wait(0.4) end\n\n            pcall(function() Events.StartDialogue:FireServer(\"Dumb guy\", model) end)\n            task.wait(0.15)\n\n            local fired = false\n            pcall(function()\n                Events.ChooseDialogueOption:FireServer(\"Dumb guy\", 1, \"GiveFish\", { model })\n                fired = true\n            end)\n\n            if origCF and root and root.Parent then\n                task.wait(0.3)\n                pcall(function() root.CFrame = origCF end)\n            end\n            return fired\n        end\n        GiveSection:CreateButton({\n            Name = \"Teleport To Duan Gan NPC\",\n            Callback = function()\n                if teleportNearNpc(\"Duan Gan\", Vector3.new(0, 3, 0)) then\n                    NexusLib:Notify({ Title = \"Duan Gan\", Message = \"Teleported!\", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = \"Duan Gan\", Message = \"NPC not found!\", Duration = 3 })\n                end\n            end\n        })\n\n        GiveSection:CreateButton({\n            Name = \"Teleport To Dumb Guy NPC\",\n            Callback = function()\n                if teleportNearNpc(\"Dumb guy\", Vector3.new(0, 3, 0)) then\n                    NexusLib:Notify({ Title = \"Dumb Guy\", Message = \"Teleported!\", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = \"Dumb Guy\", Message = \"NPC not found!\", Duration = 3 })\n                end\n            end\n        })\n\n        GiveSection:CreateButton({\n            Name = \"Give 1 Fish > 2M kg\",\n            Callback = function()\n                local list = collectBigFish(2000000)\n                if #list == 0 then\n                    NexusLib:Notify({ Title = \"Give Fish\", Message = \"No fish over 2M kg in inventory!\", Duration = 3 })\n                    return\n                end\n                local e = list[1]\n                if giveFishToDumbGuy(e) then\n                    NexusLib:Notify({ Title = \"Give Fish\", Message = \"Gave \" .. e.name .. \" (\" .. tostring(e.kg) .. \" kg)\", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = \"Give Fish\", Message = \"Failed to give fish!\", Duration = 3 })\n                end\n            end\n        })\n\n        NexusState.autoGiveFishRunning = false\n        NexusState.autoGiveFishThread = nil\n\n        Cfg.register(GiveSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Give Fish > 2M kg\", {\n            Name = \"Auto Give Fish > 2M kg\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoGiveFishRunning = value\n                if NexusState.autoGiveFishThread then\n                    pcall(task.cancel, NexusState.autoGiveFishThread)\n                    NexusState.autoGiveFishThread = nil\n                end\n                if not value then return end\n                NexusState.autoGiveFishThread = task.spawn(function()\n                    while NexusState.autoGiveFishRunning do\n                        pcall(function()\n                            local list = collectBigFish(2000000)\n                            if #list > 0 then giveFishToDumbGuy(list[1]) end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            end\n        })), \"Toggle\", \"Auto Give Fish > 2M kg\", {\n            Name = \"Auto Give Fish > 2M kg\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoGiveFishRunning = value\n                if NexusState.autoGiveFishThread then\n                    pcall(task.cancel, NexusState.autoGiveFishThread)\n                    NexusState.autoGiveFishThread = nil\n                end\n                if not value then return end\n                NexusState.autoGiveFishThread = task.spawn(function()\n                    while NexusState.autoGiveFishRunning do\n                        pcall(function()\n                            local list = collectBigFish(2000000)\n                            if #list > 0 then giveFishToDumbGuy(list[1]) end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            end\n        })\n\n        -- ===== AUTO FARthen\n                islandOk = false\n            end\n        end\n        if islandOk and (island.power or 0) <= currentPower then\n            table.insert(eligible, island)\n        end\n    end\n    table.sort(eligible, function(a, b) return a.power > b.power end)\n    NexusState.cachedRecommended = eligible[2] or eligible[1]\n    NexusState.cachedRecommendedAt = _rcNow\n    return NexusState.cachedRecommended\nend\n\nlocal function isHoldingFishingRod()\n    local char = LocalPlayer.Character\n    if not char then return false end\n    local typ = char:GetAttribute(\"Type\")\n    if typ and string.lower(tostring(typ)) == \"fishing rod\" then return true end\n    return false\nend\n\n-- ============================================================\n\n-- ============================================================\n-- ===== CONFIG SYSTEM (save / load / auto-load / import-export) =====\n-- ============================================================\n-- Every Toggle / Dropdown / MultiDropdown / Textbox with a static English Name is\n-- registered here through Cfg.wrap(kind, name, config) at creation time. The config\n-- table itself is untouched (defaults still come from Default = ...), the registry\n-- only keeps the live handle so save/load can Get/Set values later.\n--\n-- Save format is a flat { [controlName] = value } table, JSON-encoded. Control\n-- names are unique across the whole hub (verified), so no tab/section prefix is\n-- needed and configs stay compatible even if a control moves sections.\ndo\n    local ConfigSys = {}\n    ConfigSys.registry = {}   -- [name] = { kind = \"toggle\"|\"dropdown\"|\"multi\"|\"text\", get = fn, set = fn }\n    ConfigSys.ordered = {}    -- registration order, for stable exports\n    ConfigSys.FILE = \"NexusHub_Config.json\"\n    ConfigSys.AUTO_FILE = \"NexusHub_AutoLoad.json\"\n    ConfigSys._saving = false\n\n    local function cfgKind(callKind)\n        if callKind == \"Toggle\" then return \"toggle\" end\n        if callKind == \"Dropdown\" then return \"dropdown\" end\n        if callKind == \"MultiDropdown\" then return \"multi\" end\n        return \"text\"\n    end\n\n    -- Wrap a control config table: pass through untouched, remember the name so\n    -- the returned handle can be registered right after creation.\n    function ConfigSys.wrap(callKind, name, config)\n        config = config or {}\n        config._CfgKind = callKind\n        config._CfgName = name\n        return config\n    end\n\n    function ConfigSys.register(handle, callKind, name, config)\n        if not handle or not name then return handle end\n        local kind = cfgKind(callKind)\n        local entry = ConfigSys.registry[name]\n        if not entry then\n            entry = { kind = kind }\n            ConfigSys.registry[name] = entry\n            table.insert(ConfigSys.ordered, name)\n        end\n        entry.kind = kind\n        -- The original Callback is captured here at registration time (from the\n        -- config table), because NexusLib handles do not expose it.\n        local cb = config and config.Callback or nil\n        if type(handle.Get) == \"function\" then\n            entry.get = function()\n                local ok, v = pcall(handle.Get)\n                return ok and v or nil\n            end\n        end\n        -- NOTE: NexusLib Set() implementations do NOT fire Callback (toggle Set\n        -- calls set(v, false); dropdown/text Set only touch the label). After\n        -- Set we therefore re-fire the captured Callback so the hub state\n        -- (Fishing.Flags, NexusState, ...) actually follows the loaded value.\n        if type(handle.Set) == \"function\" then\n            entry.set = function(v)\n                pcall(handle.Set, handle, v)\n                if cb then\n                    task.spawn(cb, v)\n                end\n            end\n        elseif cb then\n            entry.set = function(v)\n                task.spawn(cb, v)\n            end\n        end\n        return handle\n    end\n\n    function ConfigSys.snapshot()\n        local out = {}\n        for name, entry in pairs(ConfigSys.registry) do\n            if entry.get then\n                local ok, v = pcall(entry.get)\n                if ok and v ~= nil then out[name] = v end\n            end\n        end\n        return out\n    end\n\n    function ConfigSys.apply(data)\n        if type(data) ~= \"table\" then return 0, 0 end\n        local okCount, missCount = 0, 0\n        for name, value in pairs(data) do\n            local entry = ConfigSys.registry[name]\n            if entry and entry.set then\n                local ok = pcall(entry.set, value)\n                if ok then okCount = okCount + 1 else missCount = missCount + 1 end\n            else\n                missCount = missCount + 1\n            end\n        end\n        return okCount, missCount\n    end\n\n    local function encode(data)\n        local HttpService = Services.HttpService\n        local ok, s = pcall(HttpService.JSONEncode, HttpService, data)\n        return ok and s or nil\n    end\n\n    local function decode(s)\n        local HttpService = Services.HttpService\n        local ok, data = pcall(HttpService.JSONDecode, HttpService, s)\n        if ok and type(data) == \"table\" then return data end\n        return nil\n    end\n\n    function ConfigSys.save(slot)\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Encode failed.\", Duration = 3 })\n            return false\n        end\n        if not writefile then\n            NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot save files.\", Duration = 3 })\n            return false\n        end\n        local ok = pcall(writefile, slot or ConfigSys.FILE, payload)\n        NexusLib:Notify({ Title = \"Config\", Message = ok and \"Saved.\" or \"Save failed.\", Duration = 2 })\n        return ok\n    end\n\n    function ConfigSys.load(slot, silent)\n        if not (isfile and readfile) then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot read files.\", Duration = 3 }) end\n            return false\n        end\n        local path = slot or ConfigSys.FILE\n        local has = false\n        pcall(function() has = isfile(path) end)\n        if not has then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"No saved config found.\", Duration = 3 }) end\n            return false\n        end\n        local ok, raw = pcall(readfile, path)\n        if not ok or not raw then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"Read failed.\", Duration = 3 }) end\n            return false\n        end\n        local wrap = decode(raw)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"Config file is corrupt.\", Duration = 3 }) end\n            return false\n        end\n        -- Defer one frame so every tab has finished building its controls.\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            if not silent then\n                NexusLib:Notify({ Title = \"Config\", Message = \"Loaded \" .. okCount .. \" settings\" .. (missCount > 0 and \" (\" .. missCount .. \" skipped)\" or \"\") .. \".\", Duration = 3 })\n            end\n        end)\n        return true\n    end\n\n    function ConfigSys.exportCode()\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then return nil end\n        local clip = (syn and syn.write_clipboard) or setclipboard or toclipboard\n        if clip then\n            pcall(clip, payload)\n            NexusLib:Notify({ Title = \"Config\", Message = \"Config code copied to clipboard.\", Duration = 3 })\n        else\n            NexusLib:Notify({ Title = \"Config\", Message = \"Clipboard not supported on this executor.\", Duration = 3 })\n        end\n        return payload\n    end\n\n    -- Import reads the clipboard when the executor exposes it; otherwise it falls\n    -- back to the textbox value typed/pasted by the user.\n    function ConfigSys.importCode(text)\n        local code = text\n        if (not code or code == \"\") and getclipboard then\n            pcall(function() code = getclipboard() end)\n        end\n        if not code or code == \"\" then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Paste a config code first.\", Duration = 3 })\n            return false\n        end\n        local wrap = decode(code)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Invalid config code.\", Duration = 3 })\n            return false\n        end\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            NexusLib:Notify({ Title = \"Config\", Message = \"Imported \" .. okCount .. \" settings\" .. (missCount > 0 and \" (\" .. missCount .. \" skipped)\" or \"\") .. \".\", Duration = 3 })\n        end)\n        return true\n    end\n\n    runtimeEnv.NexusConfig = ConfigSys\n    runtimeEnv.NexusCfgWrap = ConfigSys.wrap\n    ConfigSys._saving = false\nend\n\n\nlocal Cfg = runtimeEnv.NexusConfig\n\n-- ===== HOME TAB =====\n-- ============================================================\ndo\n    runtimeEnv.NexusStage(\"dung UI: Session tab\")\n    local HomeTab\n    do\n        runtimeEnv.NexusStage(\"dung UI: Session tab\")\n        local ok, result = pcall(function() return Window:CreateTab(\"Session\") end)\n        if not ok or result == nil then\n            runtimeEnv.NexusStage(\"UI Session tab failed\")\n            runtimeEnv.NexusReport(\"Nexus UI failed\", \"CreateTab Session: \" .. tostring(result))\n            return\n        end\n        HomeTab = result\n    end\n    HomeTab:CreateHeader({\n        Title = \"Session overview\",\n        Subtitle = \"Live instruments for \" .. LocalPlayer.Name\n    })\n    local statRow = HomeTab:CreateStatRow({\n        {Title = \"LEVEL\", Value = \"...\", Color = Color3.fromRGB(190, 158, 103)},\n        {Title = \"BALANCE\", Value = \"...\", Color = Color3.fromRGB(128, 159, 164)},\n        {Title = \"SESSION\", Value = \"00:00:00\", Color = Color3.fromRGB(139, 161, 142)}\n    })\n        -- Add 9 new stats\n    local statRow2 = HomeTab:CreateStatRow({\n        {Title = \"ROD\", Value = \"...\", Color = Color3.fromRGB(255, 215, 0)},\n        {Title = \"CRYSTAL\", Value = \"...\", Color = Color3.fromRGB(100, 200, 255)},\n        {Title = \"ESSENCE\", Value = \"...\", Color = Color3.fromRGB(255, 100, 200)}\n    })\n    local statRow3 = HomeTab:CreateStatRow({\n        {Title = \"BAIT\", Value = \"...\", Color = Color3.fromRGB(150, 255, 150)},\n        {Title = \"FISH CAUGHT\", Value = \"...\", Color = Color3.fromRGB(255, 200, 100)},\n        {Title = \"TICKET\", Value = \"...\", Color = Color3.fromRGB(200, 150, 255)}\n    })\n    local statRow4 = HomeTab:CreateStatRow({\n        {Title = \"TRAIT REROLL\", Value = \"...\", Color = Color3.fromRGB(255, 150, 150)},\n        {Title = \"HEAVIEST FISH\", Value = \"...\", Color = Color3.fromRGB(255, 180, 50)},\n        {Title = \"BASE HP\", Value = \"...\", Color = Color3.fromRGB(255, 100, 100)}\n    })\n    local hwid = \"N/A\"\n    pcall(function() hwid = Services.RbxAnalyticsService:GetClientId() end)\n    HomeTab:CreateFeaturedCard({\n        Tag = \"Nexus\",\n        Title = \"Heavyweight Fishing\",\n        Description = \"Script by: Ngmankhoi,NgdepZaiNhatTG,Ethangcuto\\n\\nHWID: \" .. string.sub(hwid, 1, 15) .. \"...\",\n        ButtonText = \"DISCORD\",\n        Callback = function()\n            NexusLib:Notify({ Title = \"Discord\", Message = \"Link copied to clipboard!\", Duration = 3 })\n            if setclipboard then setclipboard(\"https://discord.gg/QAdVUX2wCH\") end\n        end\n    })\n\n        local scriptStartTime = time()\n",
