"R6)_rr",2760880,'d = task.spawn(function()\n                    while NexusState.autoRebirthRunning do\n                        pcall(function()\n                            if #NexusState.selectedOptions ~= 2 then\n                                NexusLib:Notify({ Title = "Auto Rebirth", Message = "Please select exactly 2 options!", Duration = 2 })\n                                task.wait(2)\n                                return\n                            end\n                            local ok, msg = checkResources(NexusState.selectedOptions[1], NexusState.selectedOptions[2])\n                            if ok then\n                                NexusState.upgradeCharacter.teleported = false\n                                NexusState.upgradeCharacter.oldPosition = nil\n                                if NexusState.upgradeCharacter.method == "Teleport" then\n                                    local npc = Workspace:FindFirstChild("NPC")\n                                    if npc then\n                                        local func = npc:FindFirstChild("Function")\n                                        if func then\n                                            local theShadow = func:FindFirstChild("The Shadow")\n                                            if typeof(theShadow) == "Instance" and theShadow:IsA("Model") then\n                                                local hrp = theShadow:FindFirstChild("HumanoidRootPart")\n                                                if hrp then\n                                                    local char = LocalPlayer.Character\n                                                    if char then\n                                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                                        if root then\n                                                            NexusState.upgradeCharacter.oldPosition = root.Position\n                                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                                            NexusState.upgradeCharacter.teleported = true\n                                                            task.wait(0.3)\n                                                        end\n                                                    end\n                                                end\n                                            end\n                                        end\n                                    end\n                                    if not NexusState.upgradeCharacter.teleported then\n                                        NexusLib:Notify({ Title = "Auto Rebirth", Message = "Could not find The Shadow, teleport failed. Continuing anyway.", Duration = 3 })\n                                    end\n                                end\n\n                                local result = NexusState.UpgradeCharacter:InvokeServer(NexusState.selectedOptions)\n                                if result and result.ok then\n                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = "Upgraded successfully!", Duration = 2 })\n                                else\n                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = "Upgrade failed: " .. (result and result.msg or "unknown error"), Duration = 3 })\n                                end\n\n                                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                                            NexusState.upgradeCharacter.oldPosition = nil\n                                            NexusState.upgradeCharacter.teleported = false\n                                        end\n                                    end\n                                end\n                            else\n                                if math.random(1, 5) == 1 then\n                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = msg, Duration = 3 })\n                                end\n                            end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            else\n                if NexusState.autoRebirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild("HumanoidRootPart")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                            NexusState.upgradeCharacter.oldPosition = nil\n                            NexusState.upgradeCharacter.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = "Auto Rebirth", Message = "Stopped", Duration = 2 })\n            end\n        end\n    })), "Toggle", "Auto Rebirth", {\n        Name = "Auto Rebirth",\n        Default = false,\n        Callback = function(value)\n            NexusState.autoRebirthRunning = value\n            if value then\n                if NexusState.autoRebirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                NexusState.autoRebirthThread = task.spawn(function()\n                    while NexusState.autoRebirthRunning do\n                        pcall(function()\n                            if #NexusState.selectedOptions ~= 2 then\n                                NexusLib:Notify({ Title = "Auto Rebirth", Message = "Please select exactly 2 options!", Duration = 2 })\n                                task.wait(2)\n                                return\n                            end\n                            local ok, msg = checkResources(NexusState.selectedOptions[1], NexusState.selectedOptions[2])\n                            if ok then\n                                NexusState.upgradeCharacter.teleported = false\n                                NexusState.upgradeCharacter.oldPosition = nil\n                                if NexusState.upgradeCharacter.method == "Teleport" then\n                                    local npc = Workspace:FindFirstChild("NPC")\n                                    if npc then\n                                        local func = npc:FindFirstChild("Function")\n                                        if func then\n                                            local theShadow = func:FindFirstChild("The Shadow")\n                                            if typeof(theShadow) == "Instance" and theShadow:IsA("Model") then\n                                                local hrp = theShadow:FindFirstChild("HumanoidRootPart")\n                                                if hrp then\n                                                    local char = LocalPlayer.Character\n                                                    if char then\n                                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                                        if root then\n                                                            NexusState.upgradeCharacter.oldPosition = root.Position\n                                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                                            NexusState.upgradeCharacter.teleported = true\n                                                            task.wait(0.3)\n                                                        end\n                                                    end\n                                                end\n                                            end\n                                        end\n                                    end\n                                    if not NexusState.upgradeCharacter.teleported then\n                                        NexusLib:Notify({ Title = "Auto Rebirth", Message = "Could not find The Shadow, teleport failed. Continuing anyway.", Duration = 3 })\n                                    end\n                                end\n\n                                local result = NexusState.UpgradeCharacter:InvokeServer(NexusState.selectedOptions)\n                                if result and result.ok then\n                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = "Upgraded successfully!", Duration = 2 })\n                                else\n                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = "Upgrade failed: " .. (result and result.msg or "unknown error"), Duration = 3 })\n                                end\n\n                                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                                            NexusState.upgradeCharacter.oldPosition = nil\n                                            NexusState.upgradeCharacter.teleported = false\n                                        end\n                                    end\n                                end\n                            else\n                                if math.random(1, 5) == 1 then\n                                    NexusLib:Notify({ Title = "Auto Rebirth", Message = msg, Duration = 3 })\n                                end\n                            end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            else\n                if NexusState.autoRebirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild("HumanoidRootPart")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                            NexusState.upgradeCharacter.oldPosition = nil\n                            NexusState.upgradeCharacter.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = "Auto Rebirth", Message = "Stopped", Duration = 2 })\n            end\n        end\n    })\n\n    local function displayStats()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return end\n        local cash = userData:FindFirstChild("Cash") and userData.Cash.Value or 0\n        local direct = tonumber(s)\n    if direct then return direct end\n    local num, suffix = s:match("^([%d%.]+)%s*([KkMmBbTt])%+?$")\n    num = tonumber(num)\n    if not num then return nil end\n    local mult = { K = 1000, M = 1000000, B = 1000000000, T = 1000000000000 }\n    local m = mult[string.upper(suffix or "")]\n    if not m then return nil end\n    return num * m\nend\n\nlocal function parseCraftFishEntry(item)\n    if not item then return nil, nil, 0 end\n    local rawName = tostring(item.Name or "")\n    rawName = string.split(rawName, "| Favorite")[1]\n    local count = 1\n    pcall(function()\n        if type(item.Value) == "number" then count = item.Value end\n    end)\n    local parts = {}\n    for part in string.gmatch(rawName, "[^|]+") do table.insert(parts, part) end\n    local function trim(s) return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "") end\n    local fishName = trim(parts[1])\n    local weight = nil\n    if #parts >= 2 then\n        weight = parseCraftWeight(string.split(trim(parts[2]), " ")[1])\n    end\n    if not weight then\n        pcall(function()\n            local w = item:GetAttribute("Weight")\n            if type(w) == "number" and w > 0 then weight = w end\n        end)\n    end\n    if (not weight) and type(item.Value) == "string" and string.find(item.Value, "|", 1, true) then\n        local vparts = {}\n        for part in string.gmatch(item.Value, "[^|]+") do table.insert(vparts, part) end\n        if #vparts >= 2 then\n            weight = parseCraftWeight(string.split(trim(vparts[2]), " ")[1])\n        end\n        if fishName == "" and #vparts >= 1 then fishName = trim(vparts[1]) end\n    end\n    if fishName == "" then return nil, nil, 0 end\n    if type(count) ~= "number" or count < 1 then count = 1 end\n    return fishName, weight, math.floor(count)\nend\n\nlocal function GetBuyableBaits()\n    local _bbNow = tick()\n    if NexusState.cachedBuyableBaits and NexusState.cachedBuyableBaitsAt and (_bbNow - NexusState.cachedBuyableBaitsAt < 30) then\n        return NexusState.cachedBuyableBaits\n    end\n    local baits = {}\n    if not Info or not Info:FindFirstChild("Bait") then return {"No bait available"} end\n    for _, child in pairs(Info.Bait:GetChildren()) do\n        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("ModuleScript") then\n            local success, mod = pcall(require, child)\n            if success and type(mod) == "table" and mod.Price and mod.Price > 0 then\n                table.insert(baits, child.Name)\n            end\n        end\n    end\n    if #baits == 0 then return {"No bait available"} end\n    NexusState.cachedBuyableBaits = baits\n    NexusState.cachedBuyableBaitsAt = _bbNow\n    return baits\nend\n\nlocal function saveRoutineFlags()\n    NexusState.savedRoutineFlags = {\n        AutoCast = Fishing.Flags.AutoCast,\n        AnchorLock = Fishing.Flags.AnchorLock,\n        AutoSkill = Fishing.Flags.AutoSkill,\n        AutoSell = MiscFlags.AutoSell,\n        AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n        AntiAFK = Fishing.Flags.AntiAFK,\n        AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n        AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n        AutoBuy = MiscFlags.AutoBuy,\n        AutoEquipBait = MiscFlags.AutoEquipBait,\n        AutoEquipRod = MiscFlags.AutoEquipRod,\n    }\nend\n\nlocal function restoreRoutineFlags()\n    if NexusState.savedRoutineFlags then\n        Fishing.Flags.AutoCast = NexusState.savedRoutineFlags.AutoCast\n        Fishing.Flags.AnchorLock = NexusState.savedRoutineFlags.AnchorLock\n        Fishing.Flags.AutoSkill = NexusState.savedRoutineFlags.AutoSkill\n        MiscFlags.AutoSell = NexusState.savedRoutineFlags.AutoSell\n        Fishing.Flags.AutoSkillCheck = NexusState.savedRoutineFlags.AutoSkillCheck\n        Fishing.Flags.AntiAFK = NexusState.savedRoutineFlags.AntiAFK\n        Fishing.Flags.AutoFarmBoss = NexusState.savedRoutineFlags.AutoFarmBoss\n        Fishing.Flags.AutoFarmSecretBoss = NexusState.savedRoutineFlags.AutoFarmSecretBoss\n        MiscFlags.AutoBuy = NexusState.savedRoutineFlags.AutoBuy\n        MiscFlags.AutoEquipBait = NexusState.savedRoutineFlags.AutoEquipBait\n        MiscFlags.AutoEquipRod = NexusState.savedRoutineFlags.AutoEquipRod\n        NexusState.savedRoutineFlags = nil\n    else\n        Fishing.Flags.AutoFarmBoss = false\n        Fishing.Flags.AutoFarmSecretBoss = false\n    end\nend\n\n-- Ticket fishing mode: auto cast + anchor lock + auto skill + rod equip,\n-- so turning on Auto Do Ticket is enough to work all 8 ticket quests.\nlocal function enableBasicFishing()\n    if not NexusState.savedRoutineFlags then saveRoutineFlags() end\n    Fishing.Flags.AutoCast = true\n    Fishing.Flags.AnchorLock = true\n    Fishing.Flags.AutoSkill = true\n    Fishing.Flags.AutoSkillCheck = true\n    MiscFlags.AutoEquipRod = true\nend\n\nlocal function disableAllFishing()\n    restoreRoutineFlags()\nend\n\n-- Teleport without the sky-drop freeze: a character held at +1000 sky sits in\n-- freefall, so AssemblyLinearVelocity grows huge. Carrying that velocity into a\n-- ground teleport slams the Humanoid into the floor and sticks it (frozen).\n-- Zero it on both ends and wake the Humanoid so movement resumes instantly.\nlocal function safeTeleport(hrp, cf)\n    if not hrp or not cf then return end\n    local model = hrp.Parent\n    local humanoid = model and model:FindFirstChildOfClass("Humanoid")\n    -- Never freeze the live character: Anchored + task.wait() inside a\n    -- RenderStepped/Heartbeat-adjacent call stalls physics for a frame and\n    -- leaves the Humanoid seated/stuck, so walking looks frozen afterwards.\n    -- PivotTo moves the whole model atomically with no Anchored pin.\n    local ok = false\n    if model then\n        pcall(function()\n            model:PivotTo(cf)\n            ok = true\n        end)\n    end\n    if not ok then\n        pcall(function()\n            hrp.AssemblyLinearVelocity = Vector3.zero\n            hrp.AssemblyAngularVelocity = Vector3.zero\n            hrp.CFrame = cf\n        end)\n    end\n    pcall(function()\n        hrp.Anchored = false\n        hrp.AssemblyLinearVelocity = Vector3.zero\n        hrp.AssemblyAngularVelocity = Vector3.zero\n    end)\n    if humanoid then\n        pcall(function()\n            if humanoid.Seated then humanoid.Seated = false end\n            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)\n        end)\n    end\nend\n\n-- ===== EGO + TIGER CHECK (dieu kien cho Island 11) =====\n-- Island 11 chi duoc recommend khi user co ca rod Ego va Tiger trong kho.\nlocal function hasEgoAndTiger()\n    local p = GetPlayerData()\n    if not p then return false end\n    local rodFolder = p:FindFirstChild("FishingRodInventory") or p:FindFirstChild("Rod")\n    if not rodFolder then return false end\n    local hasEgo, hasTiger = false, false\n    for _, f in pairs(rodFolder:GetChildren()) do\n        local n = string.lower(tostring(f.Name))\n        if string.find(n, "ego") then hasEgo = true end\n        if string.find(n, "tiger") then hasTiger = true end\n    end\n    return hasEgo and hasTiger\nend\n\nlocal function getTotalPower()\n    local _pwNow = tick()\n    if NexusState.cachedPower and NexusState.cachedPowerAt and (_pwNow - NexusState.cachedPowerAt < 5) then\n        return NexusState.cachedPower\n    end\n    local total = 0\n    local char = LocalPlayer.Character\n    if char then\n        local stats = char:FindFirstChild("Stats")\n        if stats then\n            local rp = stats:FindFirstChild("RodPower")\n            if typeof(rp) == "Instance" and rp:IsA("NumberValue") then total = total + rp.Value end\n            local fp = stats:FindFirstChild("FishPower")\n            if typeof(fp) == "Instance" and fp:IsA("NumberValue") then total = total + fp.Value end\n        end\n        local attr = char:GetAttribute("RodPower")\n        if attr and type(attr) == "number" and attr > 0 and total == 0 then total = attr end\n    end\n    if total == 0 then\n        local userId = LocalPlayer.UserId\n        local userData = Data:FindFirstChild(tostring(userId))\n        if userData then\n            local rodNameValue = userData:FindFirstChild("FishingRod")\n            if rodNameValue then\n                local rodName = rodNameValue.Value\n                if rodName and rodName ~= "" then\n                    local rodModule = Info:FindFirstChild("Inventory") and Info.Inventory:FindFirstChild(rodName)\n                    if rodModule then\n                        local success, rodData = pcall(require, rodModule)\n                        if success and type(rodData) == "table" then\n                            total = rodData.Power or 0\n                        end\n                    end\n                end\n            end\n        end\n    end\n    NexusState.cachedPower = total\n    NexusState.cachedPowerAt = _pwNow\n    return total\nend\n\nlocal function getRecommendedIsland()\n    local _rcNow = tick()\n    if NexusState.cachedRecommended and NexusState.cachedRecommendedAt and (_rcNow - NexusState.cachedRecommendedAt < 5) then\n        return NexusState.cachedRecommended\n    end\n    local currentPower = getTotalPower()\n    local eligible = {}\n    for _, island in ipairs(NexusState.islands) do\n        -- Island 11 (if u have ego and tiger): chi chon khi co ca rod Ego va Tiger\n        if island.name ~= "Island 11" or hasEgoAndTiger() then\n            if (island.power or 0) <= currentPower then\n                table.insert(eligible, island)\n            end\n        end\n    end\n    table.sort(eligible, function(a, b) return a.power > b.power end)\n    NexusState.cachedRecommended = eligible[2] or eligible[1]\n    NexusState.cachedRecommendedAt = _rcNow\n    return NexusState.cachedRecommended\nend\n\nlocal function isHoldingFishingRod()\n    local char = LocalPlayer.Character\n    if not char then return false end\n    local typ = char:GetAttribute("Type")\n    if typ and string.lower(tostring(typ)) == "fishing rod" then return true end\n    return false\nend\n\n-- ============================================================\n\n-- ============================================================\n-- ===== CONFIG SYSTEM (save / load / auto-load / import-export) =====\n-- ============================================================\n-- Every Toggle / Dropdown / MultiDropdown / Textbox with a static English Name is\n-- registered here through Cfg.wrap(kind, name, config) at creation time. The config\n-- table itself is untouched (defaults still come from Default = ...), the registry\n-- only keeps the live handle so save/load can Get/Set values later.\n--\n-- Save format is a flat { [controlName] = value } table, JSON-encoded. Control\n-- names are unique across the whole hub (verified), so no tab/section prefix is\n-- needed and configs stay compatible even if a control moves sections.\ndo\n    local ConfigSys = {}\n    ConfigSys.registry = {}   -- [name] = { kind = "toggle"|"dropdown"|"multi"|"text", get = fn, set = fn }\n    ConfigSys.ordered = {}    -- registration order, for stable exports\n    ConfigSys.FILE = "NexusHub_Config.json"\n    ConfigSys.AUTO_FILE = "NexusHub_AutoLoad.json"\n    ConfigSys._saving = false\n\n    local function cfgKind(callKind)\n        if callKind == "Toggle" then return "toggle" end\n        if callKind == "Dropdown" then return "dropdown" end\n        if callKind == "MultiDropdown" then return "multi" end\n        return "text"\n    end\n\n    -- Wrap a control config table: pass through untouched, remember the name so\n    -- the returned handle can be registered right after creation.\n    function ConfigSys.wrap(callKind, name, config)\n        config = config or {}\n        config._CfgKind = callKind\n        config._CfgName = name\n        return config\n    end\n\n    function ConfigSys.register(handle, callKind, name, config)\n        if not handle or not name thetude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n            if not bestHRP then\n                for _, desc in ipairs(npcFolder:GetDescendants()) do\n                    if typeof(desc) == "Instance" and typeof(desc) == "Instance" and desc:IsA("Model") and string.find(desc.Name:lower(), "bait") then\n                        local hrp = desc:FindFirstChild("HumanoidRootPart") or desc:FindFirstChild("Torso") or desc.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magnitude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end)\n    return bestHRP\nend\n\n-- ============================================================\n-- ===== AUTO FARM HELPERS =====\n-- ============================================================\n\n-- Check whether Auto Farm Boss is enabled\nlocal function bossFarmEnabled()\n    return NexusState.Fishing.Flags.AutoFarmBoss or NexusState.Fishing.Flags.AutoFarmSecretBoss\nend\n\n-- Reset Boss Farm state\nlocal function resetBossFarmTarget()\n    NexusState.Fishing.BossFarm.CurrentTarget = nil\n    NexusState.Fishing.BossFarm.CurrentType = nil\n    NexusState.Fishing.BossFarm.CurrentToken = nil\n    NexusState.Fishing.BossFarm.HasHooked = false\n    NexusState.Fishing.BossFarm.PendingCancel = false\nend\n\n-- Read info about the target currently biting\nlocal function getCurrentHookTarget()\n    local target = NexusState.Fishing.BossFarm.CurrentTarget\n    local info = { Name = nil, Data = nil, Instance = nil, Boss = false, SecretBoss = false }\n\n    if type(target) == "table" then\n        info.Data = target\n        info.Name = target.FishName or target.Name or target.fishName\n        info.Boss = target.Boss == true or target.SpecialBoss == true or target.SecretBoss == true\n        info.SecretBoss = target.SecretBoss == true\n    elseif typeof and typeof(target) == "Instance" then\n        info.Instance = target\n        info.Name = target:GetAttribute("FishName") or target.Name\n        info.Boss = target:GetAttribute("Boss") == true or target:GetAttribute("SpecialBoss") == true or target:GetAttribute("SecretBoss") == true\n        info.SecretBoss = target:GetAttribute("SecretBoss") == true\n    elseif type(target) == "string" then\n        info.Name = target\n    end\n\n    local fishId = LocalPlayer:GetAttribute("FishID")\n    local fishes = Workspace:FindFirstChild("Fishes")\n    local fishInstance = fishId and fishes and fishes:FindFirstChild(tostring(fishId))\n\n    if fishInstance then\n        info.Instance = fishInstance\n        info.Name = info.Name or fishInstance:GetAttribute("FishName") or fishInstance.Name\n        info.Boss = info.Boss or fishInstance:GetAttribute("Boss") == true or fishInstance:GetAttribute("SpecialBoss") == true or fishInstance:GetAttribute("SecretBoss") == true\n        info.SecretBoss = info.SecretBoss or fishInstance:GetAttribute("SecretBoss") == true\n    end\n\n    local fishingGui = MainGui:FindFirstChild("Fishing")\n    local progression = fishingGui and fishingGui:FindFirstChild("ProgressionBar")\n    local fishNameLabel = progression and progression:FindFirstChild("FishName")\n\n    if (not info.Name or info.Name == "" or info.Name == "???") and fishNameLabel and fishNameLabel.Text ~= "" then\n        info.Name = fishNameLabel.Text\n    end\n\n    return info\nend\n\nlocal function textHasKeyword(text, keywords)\n    text = string.lower(tostring(text or ""))\n    for _, keyword in ipairs(keywords) do\n        if string.find(text, keyword, 1, true) then return true end\n    end\n    return false\nend\n\n-- Check whether the target is a Secret Boss\nlocal function isSecretBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    local name = string.lower(tostring(current.Name or ""))\n    return current.SecretBoss or NexusState.SecretBossNameSet[name] or textHasKeyword(name, NexusState.SecretBossKeywords)\nend\n\n-- Check whether the target is a Boss\nlocal function isBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    local name = string.lower(tostring(current.Name or ""))\n    if isSecretBossTarget(current) then return true end\n    return current.Boss or NexusState.BossNameSet[name] or textHasKeyword(name, NexusState.BossKeywords)\nend\n\n-- Decide whether this target should be farmed\nlocal function shouldFarmBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    if isSecretBossTarget(current) then return true, "Secret Boss" end\n    if NexusState.Fishing.Flags.AutoFarmSecretBoss and not NexusState.Fishing.Flags.AutoFarmBoss then return false, "Normal" end\n    if NexusState.Fishing.Flags.AutoFarmBoss and isBossTarget(current) then return true, "Boss" end\n    return false, "Normal"\nend\n\n-- Cancel the cast or release a common fish\nlocal function cancelOrReleaseNormalFish()\n    if not bossFarmEnabled() then return false end\n    local character = LocalPlayer.Character\n    if not character then return false end\n    if not character:GetAttribute("Fishing") then resetBossFarmTarget(); return true end\n\n    NexusState.Fishing.BossFarm.PendingCancel = true\n\n    pcall(function()\n        local fishingGui = MainGui:FindFirstChild("Fishing")\n        local barFrame = fishingGui and fishingGui:FindFirstChild("BarFrame")\n        local bar = barFrame and barFrame:FindFirstChild("Bar")\n        if bar then bar.Position = UDim2.new(-0.15, 0, bar.Position.Y.Scale, bar.Position.Y.Offset) end\n    end)\n\n    if NexusState.Fishing.BossFarm.CurrentToken and tick() - NexusState.Fishing.BossFarm.LastFastCancel > 0.5 then\n        NexusState.Fishing.BossFarm.LastFastCancel = tick()\n        pcall(function() Events.FishingMinigame:FireServer(false, NexusState.Fishing.BossFarm.CurrentToken) end)\n    end\n\n    if not character:GetAttribute("Retractable") then return false end\n    if tick() - NexusState.Fishing.BossFarm.LastCancel < 0.35 then return false end\n\n    NexusState.Fishing.BossFarm.LastCancel = tick()\n    pcall(function()\n        local root = character:FindFirstChild("HumanoidRootPart")\n        if root then Events.Fishing:FireServer(root.CFrame) end\n    end)\n\n    return false\nend\n\n-- textHasKeyword helper (if not defined yet)\nif not textHasKeyword then\n    local function textHasKeyword(text, keywords)\n        text = string.lower(tostring(text or ""))\n        for _, keyword in ipairs(keywords) do\n            if string.find(text, keyword, 1, true) then return true end\n        end\n        return false\n    end\nend\n\nlocal function loadBossNameSets()\n    for k in pairs(NexusState.BossNameSet) do NexusState.BossNameSet[k] = nil end\n    for k in pairs(NexusState.SecretBossNameSet) do NexusState.SecretBossNameSet[k] = nil end\n    local infoFolder = ReplicatedStorage:FindFirstChild("Info")\n    if not infoFolder then return end\n\n    pcall(function()\n        local areaRarity = infoFolder:FindFirstChild("FishingAreaRarity")\n        if areaRarity then\n            local rarityData = require(areaRarity)\n            if type(rarityData) == "table" and type(rarityData["Secret Boss"]) == "table" then\n                for fishName in pairs(rarityData["Secret Boss"]) do\n                    local name = string.lower(tostring(fishName))\n                    NexusState.SecretBossNameSet[name] = true\n                    NexusState.BossNameSet[name] = true\n                end\n            end\n        end\n    end)\n\n    pcall(function()\n        local inventory = infoFolder:FindFirstChild("Inventory")\n        if inventory then\n            for _, module in pairs(inventory:GetChildren()) do\n                if typeof(module) == "Instance" and typeof(module) == "Instance" and module:IsA("ModuleScript") then\n                    local ok, itemData = pcall(require, module)\n                    if ok and type(itemData) == "table" then\n                        local name = string.lower(tostring(itemData.FishName or module.Name))\n                        if itemData.Boss == true or itemData.SpecialBoss == true or itemData.SecretBoss == true then\n                            NexusState.BossNameSet[name] = true\n                        end\n                        if itemData.SecretBoss == true then\n                            NexusState.SecretBossNameSet[name] = true\n                        end\n                    end\n                end\n            end\n        end\n    end)\nend\n-- Defer heavy boss-name scan until after boot so opening the hub stays smooth\ntask.spawn(function()\n    task.wait(3)\n    if not alive() then return end\n    pcall(loadBossNameSets)\nend)\n\n-- ===== BUILD MAIN UI =====\nruntimeEnv.NexusStage("dung UI")\nlocal Window\ndo\n    local ok, result = pcall(function()\n        return NexusLib:CreateWindow({\n            Title = "NEXUS",\n            Subtitle = "HEAVYWEIGHT FISHING - LIVE SESSION",\n            Keybind = Enum.KeyCode.RightAlt,\n        })\n    end)\n    if not ok or type(result) ~= "table" then\n        runtimeEnv.NexusStage("UI window failed")\n        runtimeEnv.NexusReport("Nexus UI failed", "CreateWindow: " .. tostring(result))\n        return\n    end\n    Window = result\nend\n\nlocal Fishing = NexusState.Fishing\nlocal MiscFlags = NexusState.MiscFlags\n\n-- ============================================================\n-- ===== SHARED HELPERS (DECLARED UP FRONT) =====\n-- ============================================================\n\nlocal function GetPlayerData()\n    if not Data then return nil end\n    return Data:FindFirstChild(tostring(LocalPlayer.UserId))\nend\n\nlocal function GetModule(folder, name)\n    local m = folder:FindFirstChild(name)\n    if m then\n        local ok, mod = pcall(require, m)\n        if ok and type(mod) == "table" then return mod end\n    end\n    return nil\nend\n\nlocal function GetAvailableBaits()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local baits = {}\n    local baitFolder = p:FindFirstChild("Bait")\n    if not baitFolder then return {} end\n    for _, b in pairs(baitFolder:GetChildren()) do\n        if typeof(b) == "Instance" and typeof(b) == "Instance" and b:IsA("NumberValue") and b.Value > 0 then\n            table.insert(baits, b.Name)\n        end\n    end\n    return baits\nend\n\nlocal function GetBaitStats(baitName)\n    local mod = GetModule(Info.Bait, baitName)\n    if mod then return {Luck = mod.Luck or 0} end\n    return {Luck = 0}\nend\n\nlocal function GetBestBait()\n    local baits = GetAvailableBaits()\n    local best, bestLuck = nil, -1\n    for _, name in ipairs(baits) do\n        local s = GetBaitStats(name)\n        if s.Luck > bestLuck then bestLuck = s.Luck; best = name end\n    end\n    return best\nend\n\nlocal function EquipBait(baitName)\n    if not baitName then return false end\n    return pcall(function() Events.EquipBait:InvokeServer(baitName) end)\nend\n\nlocal function GetOwnedRods()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local rods = {}\n    for _, f in pairs(p.FishingRodInventory:GetChildren()) do\n        if typeof(f) == "Instance" and typeof(f) == "Instance" and f:IsA("Folder") and f.Owned and f.Owned.Value == true then\n            table.insert(rods, f.Name)\n        end\n    end\n    return rods\nend\n\nlocal function GetRodStats(rodName)\n    local mod = GetModule(Info.Inventory, rodName)\n    if mod then return {Power = mod.Power or 0, Luck = mod.Luck or 0} end\n    return {Power = 0, Luck = 0}\nend\n\nl